  'AI এই মুহূর্তে বন্ধ আছে।': 'AI is off right now.',
  'AI চালু থাকলে Anthropic-এ যায়: আপনার বলা বা লেখা বাক্য, টাকার হিসাবের সারাংশ (নাম ও অঙ্ক), রিমাইন্ডার, কাজ, নোট, অভ্যাসের নাম, বিশেষ দিন, ডকুমেন্টের নাম আর “মনে রেখো” কথাগুলো — যাতে আপনার জিনিস নিয়ে ঠিক উত্তর দিতে পারে। কখনো যায় না: পাসওয়ার্ড ও ভল্ট, PIN/OTP/পাসওয়ার্ড থাকা নোট, ওষুধ, স্বাস্থ্যের মাপ, ওষুধ-ডাক্তার-অসুখের কথা থাকা রিমাইন্ডার-কাজ-নোট, ফোন-কার্ড-NID নম্বর, ইমেইল আর অন্য অ্যাপের মেসেজ।': 'With the AI on, Anthropic gets: what you say or type, a money summary (names and amounts), reminders, to-dos, notes, habit names, special days, document names and your “remember” notes — so it can answer about your things. Never sent: passwords and the vault, notes with PINs/OTPs/passwords, medicines, health readings, reminders/to-dos/notes about medicine, doctors or illness, phone/card/ID numbers, e-mails and other apps’ messages.',
  'AI চালু থাকলে আপনার বলা বাক্য, টাকার হিসাবের সারাংশ, রিমাইন্ডার, কাজ আর নোট Anthropic-এ যায়, যাতে আপনার জিনিস নিয়ে প্রশ্নের ঠিক উত্তর দিতে পারে; পাসওয়ার্ড, ভল্ট, PIN, ফোন নম্বর বা গোপন কোড থাকা নোট কখনো যায় না।': 'With AI on, what you say, a summary of your money, reminders, tasks and notes go to Anthropic so it can answer questions about your things correctly; passwords, the vault, PINs, phone numbers or notes with secret codes never go.',
  'AI চালু থাকলে আপনার বলা বাক্য, লেনদেনের মানুষের নাম আর টাকার হিসাবের সারাংশ Anthropic-এ যায়; পাসওয়ার্ড, ভল্ট, PIN, ফোন নম্বর, নোট বা কাজের লেখা যায় না।': 'With AI on, what you say, names of people you deal with and a summary of your money go to Anthropic; passwords, the vault, PINs, phone numbers, notes or task text never go.',
  'AI চালু থাকলে শুধু আপনার বলা বা লেখা বাক্য আর টাকার হিসাবের সারাংশ (নাম ও অঙ্ক) Anthropic-এ যায়। রিমাইন্ডার, কাজ, নোট, পাসওয়ার্ড, ভল্ট, ফোন-কার্ড-NID নম্বর বা অন্য অ্যাপের মেসেজ যায় না।': 'With the AI on, only what you say or type and a money summary (names and amounts) go to Anthropic. Reminders, to-dos, notes, passwords, the vault, phone/card/ID numbers and other apps\' messages do not.',
