  'Google দিয়ে লগইন করলে তথ্য আপনার Google Drive-এর অ্যাপের লুকানো ফোল্ডারে ব্যাকআপ রাখা যাবে। নতুন ফোনে একই অ্যাকাউন্টে লগইন করলেই সব ফিরে আসবে — কোনো পাসওয়ার্ড লাগবে না। ব্যাকআপ তালাবদ্ধ থাকে: Google একা বা আমরা একা খুলতে পারি না।': 'Sign in with Google to keep backups in the app’s hidden folder in your Google Drive. Sign in with the same account on a new phone and everything comes back — no password needed. Backups are locked: neither Google nor we alone can open them.',
  'Google দিয়ে লগইন করলে তথ্য আপনার Google Drive-এর অ্যাপের লুকানো ফোল্ডারে ব্যাকআপ রাখা যাবে। নতুন ফোনে একই অ্যাকাউন্টে লগইন করলেই সব ফিরে আসবে। ব্যাকআপ আপনার পাসওয়ার্ডে তালাবদ্ধ — Google বা আমরা পড়তে পারি না।': 'Sign in with Google to keep backups in the app’s hidden folder in your Google Drive. Sign in with the same account on a new phone and everything comes back. Backups are locked with your password — neither Google nor we can read them.',
  'Google দিয়ে লগইন করলে তথ্য নিজে থেকে আপনার Google Drive-এর অ্যাপের লুকানো ফোল্ডারে ব্যাকআপ হবে। নতুন ফোনে একই অ্যাকাউন্টে লগইন করলেই সব ফিরে আসবে। ব্যাকআপ আপনার পাসওয়ার্ডে তালাবদ্ধ — Google বা আমরা পড়তে পারি না।': 'Sign in with Google and your data backs up by itself to the app’s hidden folder in your Google Drive. On a new phone, sign in with the same account and everything comes back. The backup is locked with your password — neither Google nor we can read it.',
  'Google বা আমরা আপনার ব্যাকআপ পড়তে পারি না — সেটা আপনার পাসওয়ার্ডে তালাবদ্ধ থাকে।': 'Neither Google nor we can read your backup — it is locked with your password.',
