  'PIN মেলেনি। আর {0} বার চেষ্টা করা যাবে।': 'Wrong PIN. {0} tries left.',
  'PIN শুধু এই ফোনে, এনক্রিপ্ট করে রাখা হয়। ভুলে গেলে আঙুলের ছাপ বা Google Drive ব্যাকআপের পাসওয়ার্ড দিয়ে নতুন PIN দেওয়া যাবে।': 'The PIN is kept only on this phone, encrypted. If you forget it, your fingerprint or the Google Drive backup password can set a new one.',
  'PIN শুধু এই ফোনে, এনক্রিপ্ট করে রাখা হয়। ভুলে গেলে আঙুলের ছাপ বা একই Google অ্যাকাউন্ট দিয়ে নতুন PIN দেওয়া যাবে।': 'The PIN stays on this phone, encrypted. If you forget it, your fingerprint or the same Google account lets you set a new one.',
  'PIN শুধু এই ফোনে, এনক্রিপ্ট করে রাখা হয়। ভুলে গেলে তথ্য ফেরত আনা যাবে না — ব্যাকআপ রাখুন।': 'The PIN is kept only on this phone, encrypted. If you forget it your data can\'t be recovered — keep a backup.',
  'WhatsApp খোলা গেল না': 'Couldn\'t open WhatsApp',
  'WhatsApp, SMS, বিকাশের মেসেজ থেকে নিজে হিসাব আর কাজ বানায়': 'Makes entries and tasks from WhatsApp, SMS and bKash messages',
  'WhatsApp, Telegram, imo, Messenger, Gmail, SMS-এ নতুন মেসেজ এলে সহকারী নোটিফিকেশন থেকে তা পড়বে, আর মিটিং, টাকা চাওয়া, বিল, উত্তর দেওয়ার মতো কাজগুলো আলাদা করে দেখাবে। এক চাপে রিমাইন্ডার বা কাজ বানাতে, এখান থেকেই উত্তর দিতে পারবেন।': 'When a new WhatsApp, Telegram, imo, Messenger, Gmail or SMS message arrives, the assistant reads it from the notification and picks out meetings, money requests, bills and questions to answer. Make a reminder or to-do in one tap, and reply from here.',
  'WhatsApp, Telegram, imo, Messenger, Gmail, SMS-এর নতুন মেসেজ পড়ে মিটিং, টাকা চাওয়া, বিল, উত্তর দেওয়ার কাজ আলাদা করে; এক চাপে রিমাইন্ডার, এখান থেকেই উত্তর।': 'Reads new WhatsApp, Telegram, imo, Messenger, Gmail and SMS messages and picks out meetings, money requests, bills and replies due; a reminder in one tap, and replies from here.',
  'WhatsApp-এ পাঠান': 'Send on WhatsApp',
  'Wi-Fi-এর কোনো তথ্য এখনো রাখা হয়নি। চাইলে এখনই রেখে দিতে পারেন।': 'No Wi-Fi details saved yet. You can save them now.',
  'Wi-Fi-এর কোনো তথ্য নেই। পাসওয়ার্ড ভল্টে তথ্যটি যুক্ত করতে পারেন — পরে জিজ্ঞেস করলে আঙুলের ছাপ নিয়ে দেখাবো।': 'There\'s no Wi-Fi information. Add it to the password vault; when you ask, I\'ll show it after your fingerprint.',
