  'key দিলে AI চালু হবে: আপনার বলা বা লেখা বাক্য আর হিসাবের সারাংশ Anthropic-এ যাবে (কী কী যায়, সেটিংসে নিচে লেখা আছে)। পাসওয়ার্ড, ভল্ট, PIN/OTP আর ফোন-কার্ড-NID নম্বর কখনো যায় না। key মুছে দিলেই AI বন্ধ। key এই ফোনে তালাবদ্ধ থাকে।': 'With a key the AI turns on: what you say or type and a money summary go to Anthropic (the full list is in Settings below). Passwords, the vault, PINs/OTPs and phone, card or ID numbers never go. Remove the key to turn the AI off. The key stays locked on this phone.',
