  'দিক ঠিকমতো ধরতে পারছে না — ফোনটা বাতাসে ইংরেজি ৮-এর মতো কয়েকবার ঘোরান, আর চুম্বক বা লোহার জিনিস থেকে দূরে রাখুন।': 'The direction is unsteady — move the phone in a figure 8 a few times, away from magnets and iron.',
  'ফোন সমান করে বা সামনে খাড়া করে — যেভাবে সুবিধা ধরুন; ফোনের মাথা যেদিকে, দিক সেটাই। প্রথমবার ফোনটা বাতাসে কয়েকবার ৮ আঁকার মতো ঘোরান। লোহা, চুম্বক, স্পিকার, ল্যাপটপ বা চুম্বকওয়ালা কভার থেকে দূরে রাখুন — এগুলো দিক বদলে দেয়। কিবলার দিক আপনার জেলার হিসেবে; মসজিদের দিক মিলিয়ে নেওয়া ভালো।': 'Hold the phone flat or upright in front of you, as you like; it shows where the top of the phone points. The first time, wave the phone in a figure 8 a few times. Keep it away from iron, magnets, speakers, laptops and magnetic covers — they bend the direction. The qibla is worked out from your district; it is good to check against a mosque.',
  'উ': 'N',
  'পূ': 'E',
  'দ': 'S',
  'প': 'W',
  'উত্তর': 'north',
  'উত্তর-পূর্ব': 'north-east',
  'পূর্ব': 'east',
  'দক্ষিণ-পূর্ব': 'south-east',
  'দক্ষিণ': 'south',
  'দক্ষিণ-পশ্চিম': 'south-west',
  'পশ্চিম': 'west',
  'উত্তর-পশ্চিম': 'north-west',
  'প্রবাদ': 'Saying',
  'বেঞ্জামিন ফ্র্যাংকলিন, “দ্য ওয়ে টু ওয়েলথ”': 'Benjamin Franklin, “The Way to Wealth”',
  'সূরা বনী ইসরাঈল, ১৭:২৬-২৭': 'Surah Al-Isra, 17:26-27',
  'সূরা আল-ফুরকান, ২৫:৬৭': 'Surah Al-Furqan, 25:67',
  'আয় বুঝে ব্যয় করো।': 'Spend according to what you earn.',
  'খরচের পর যা থাকে তা জমাবেন না; জমানোর পর যা থাকে, তা খরচ করুন।': 'Don\'t save what is left after spending; spend what is left after saving.',
  'ছোট খরচগুলোকে অবহেলা করবেন না — ছোট একটা ফুটোই বড় জাহাজ ডুবিয়ে দিতে পারে।': 'Beware of little expenses; a small leak will sink a great ship.',
  'আর তোমরা অপচয় কোরো না। নিশ্চয়ই অপচয়কারীরা শয়তানের ভাই।': 'And do not spend wastefully. Indeed, the wasteful are brothers of the devils.',
  'আর যারা ব্যয় করার সময় অপব্যয় করে না, কৃপণতাও করে না — বরং এ দুয়ের মাঝামাঝি থাকে।': 'And those who, when they spend, are neither wasteful nor stingy, but hold a just balance between the two.',
  'বিন্দু বিন্দু জলে সিন্ধু হয় — প্রতিদিনের অল্প সঞ্চয়ই একদিন বড় সম্বল।': 'Drops make an ocean — a little saved every day becomes a real reserve.',
  'যা দরকার তা কিনুন; যা ভালো লাগে, তা কেনার আগে এক দিন অপেক্ষা করুন।': 'Buy what you need; for what you merely like, wait a day first.',
  'বেতন হাতে আসার দিনই আগে সঞ্চয়ের অংশটা সরিয়ে রাখুন — পরে আর থাকে না।': 'Put the savings part aside the day your salary arrives — later it is gone.',
  'তিন থেকে ছয় মাসের খরচের সমান টাকা বিপদের জন্য আলাদা রাখুন।': 'Keep three to six months of expenses aside for emergencies.',
  'ধার করে শখ মেটানো মানে ভবিষ্যতের আয় আজ খরচ করে ফেলা।': 'Borrowing for wants is spending tomorrow\'s income today.',
  'প্রতিটা খরচ লিখে রাখুন — না লিখলে বোঝাই যায় না টাকা কোথায় যায়।': 'Write down every expense — otherwise you never see where the money goes.',
  'আয়ের মোটামুটি অর্ধেক প্রয়োজনে, এক-তৃতীয়াংশের কম শখে, আর অন্তত এক-পঞ্চমাংশ সঞ্চয়ে।': 'About half of income on needs, under a third on wants, and at least a fifth saved.',
  'দামি জিনিস নয়, দরকারি জিনিস কিনুন।': 'Buy what is useful, not what is expensive.',
  'বাইরে খাওয়া মাঝে মাঝে আনন্দ; প্রতিদিন হলে বড় খরচ।': 'Eating out now and then is a treat; every day, it is a big expense.',
  'ঋণ নেওয়ার আগে ভাবুন — কিস্তি দেওয়ার দিনও আসবে।': 'Think before borrowing — the instalment days will come too.',
  'অন্যকে দেখে খরচ করবেন না; নিজের আয় দেখে করুন।': 'Don\'t spend by looking at others; spend by looking at your income.',
  'ছাড় দেখে কেনা নয় — দরকার থাকলে তবেই ছাড় কাজে লাগে।': 'Don\'t buy because of a discount — a discount helps only if you need the thing.',
  'মাসের শুরুতেই একটা খরচের সীমা ঠিক করুন, শেষে মিলিয়ে দেখুন।': 'Set a spending limit at the start of the month and check it at the end.',
  'পাওনা টাকা সময়মতো তুলুন, দেনা সময়মতো শোধ করুন — সম্পর্ক আর হিসাব দুটোই ভালো থাকে।': 'Collect what you are owed and repay what you owe on time — both friendships and accounts stay healthy.',
  'শিক্ষা আর স্বাস্থ্যে খরচ খরচ নয়, বিনিয়োগ।': 'Spending on education and health is not an expense but an investment.',
  'অল্প আয়েও সঞ্চয় সম্ভব — শুরুটা যত ছোটই হোক।': 'Saving is possible even on a small income — however small the start.',
  'বিল আর কিস্তির তারিখ মনে রাখলে জরিমানার টাকা বাঁচে।': 'Remembering bill and instalment dates saves the late fees.',
  'যে খরচ না করলেও চলে, সপ্তাহে একবার তার তালিকা করুন — অর্ধেক কমালেই অনেক বাঁচে।': 'Once a week, list the spending you could do without — halving it saves a lot.',
  'হঠাৎ পাওয়া টাকা হঠাৎ খরচ নয় — আগে একটা অংশ জমা রাখুন।': 'Sudden money is not for sudden spending — save a part first.',
  'দান করলে সম্পদ কমে না — নিজের সামর্থ্য বুঝে নিয়মিত দিন।': 'Giving does not make you poorer — give regularly, as you can afford.',
  'মোবাইলে কেনাকাটা সহজ, তাই সাবধানও হতে হয় বেশি।': 'Shopping on the phone is easy, so be all the more careful.',
  'ধীরে ধীরে জমানো টাকা হঠাৎ পাওয়া টাকার চেয়ে বেশি দিন থাকে।': 'Money saved slowly lasts longer than money that came suddenly.',
  'পরিবারের সবাই মিলে বাজেট করলে খরচ কমানো সহজ হয়।': 'Budgeting together as a family makes cutting costs easier.',
  'টাকা ভালো ভৃত্য, কিন্তু খারাপ মালিক।': 'Money is a good servant but a bad master.',
  'আজকের ছোট সংযম কালকের বড় স্বস্তি।': 'A little restraint today is great relief tomorrow.',
  'আপনি ‘{0}’ নামে আলাদা হিসাব চেয়েছিলেন — অন্যান্য হিসাবে খুলে দিই?': 'You asked for a separate account called ‘{0}’ — shall I open it under other accounts?',
  'হ্যাঁ, খুলে দাও': 'Yes, open it',
  'দুঃখিত, আগে ঠিক উত্তর দিইনি। আপনি ‘{0}’ নামে আলাদা হিসাব চেয়েছেন — অন্যান্য হিসাবে খুলে দিই?': 'Sorry, I didn\'t answer that right. You asked for a separate account called ‘{0}’ — shall I open it under other accounts?',
  'খুলে দেবো কিনা — হ্যাঁ বা না বলুন।': 'Shall I open it — say yes or no.',
  'আচ্ছা, খুললাম না।': 'OK, I didn\'t open it.',
  '{0} {1}-এ': 'in {0} {1}',
  'ঠিক আছে, {0}টা কাজ {1} রাখলাম।': 'OK, {0} to-dos are now {1}.',
  '‘{0}’ নামে হিসাব আগেই খোলা আছে — অন্যান্য হিসাবে পাবেন।': 'An account called ‘{0}’ is already open — under other accounts.',
  '‘{0}’ নামে আলাদা কোনো হিসাব এখনো নেই। অন্যান্য হিসাবে ‘{0}’ খুলে দিই?': 'There is no separate account called ‘{0}’ yet. Shall I open ‘{0}’ under other accounts?',
  '“{0}” খাতে আজ কোনো খরচ লেখা নেই। রাখতে চাইলে বলুন, যেমন “{0} {1} টাকা খরচ”।': 'Nothing is written under “{0}” today. To add it, say e.g. “{0} {1} taka spent”.',
  'হ্যাঁ, {0} — {1} টাকা লেখা আছে ({2})।': 'Yes, {0} — {1} taka is written ({2}).',
  'না — {0} লেখা আছে {1} টাকা ({2}), {3} নয়। ভুল হলে বলুন “{0} {3} টাকা হবে”।': 'No — {0} is written as {1} taka ({2}), not {3}. If that is wrong, say “{0} should be {3} taka”.',
  '‘{0}’ নামে হিসাব আগেই খোলা আছে।': 'An account called ‘{0}’ is already open.',
  'নতুন অন্যান্য হিসাব খোলা প্রিমিয়াম সুবিধা — প্রিমিয়াম চালু করলে খুলে দিতে পারব।': 'Opening another account is a Premium feature — with Premium I can open it.',
  'খুলে দিলাম — অন্যান্য হিসাবে ‘{0}’। এখন বলুন, যেমন “মাহি ২০০০ টাকা দিয়েছে, {0} হিসাবে”।': 'Opened ‘{0}’ under other accounts. Now say, e.g. “Mahi gave 2000 taka, in {0}”.',
  'কোন কাজগুলোর কথা বলছেন, খুঁজে পেলাম না — যেমন বলুন “কালকের প্রতিটি কাজের রিমাইন্ডার দাও, সকাল ৯টায়”।': 'I couldn\'t find which to-dos you mean — say e.g. “a reminder for each of tomorrow\'s to-dos at 9 am”.',
  'যেগুলোর নির্দিষ্ট দিন নেই, সেগুলো মাস/বছরের প্রথম দিনে রাখলাম।': 'Those without a set day are on the first day of their month or year.',
  '{0}টার সময় পেরিয়ে গেছে, ওগুলোতে দিইনি।': '{0} had already passed, so none was set for them.',
  'ঠিক আছে, {0}টা কাজের রিমাইন্ডার {1}-এ রাখলাম।': 'OK, reminders for {0} to-dos at {1}.',
  '“বাজারের কাজটা মুছে দাও”': '“remove the shopping to-do”',
  '“মিটিংয়ের রিমাইন্ডারটা মুছে দাও”': '“remove the meeting reminder”',
  '“ওয়াইফাইয়ের নোটটা মুছে দাও”': '“remove the wifi note”',
  '“রহিমের ৫০০ টাকার লেনদেনটা মুছে দাও”': '“remove Rahim\'s 500 taka entry”',
  'কোনটা {0}, খুঁজে পেলাম না। নাম বা তারিখ বলে আরেকবার বলুন — যেমন {1}।': 'I couldn\'t find which one to {0}. Say it again with its name or date — e.g. {1}.',
  'দুঃখিত। শেষে রেখেছি: {0}। কোনটা ভুল — নাম, তারিখ, না পুরোটাই? বলুন কী হবে, অথবা “ফিরিয়ে নাও” বললে ওটা সরিয়ে দেব।': 'Sorry. The last thing I kept: {0}. What is wrong — the name, the date, or all of it? Tell me, or say “undo” and I\'ll take it back.',
  'কোন তারিখ? যেমন “১০ তারিখে” ({0})।': 'Which date? E.g. “the 10th” ({0}).',
  'রিমাইন্ডারটা রাখা হয়েছে ({0}), কিন্তু ফোনে সেট করা যায়নি — তাই এখনো বাজবে না। অ্যাপটা একবার বন্ধ করে খুলুন; তবু না হলে রিমাইন্ডার পাতা থেকে আবার চালু করুন।': 'The reminder is kept ({0}), but the phone could not set it — so it won\'t ring yet. Close and reopen the app; if it still fails, turn it on again from the reminders page.',
  'ফিরিয়ে নেওয়ার মতো শেষ কোনো পরিবর্তন পেলাম না — মুছে ফেলা জিনিস “মুছে ফেলা” পাতা থেকে ফেরত আনা যায়।': 'There is no last change I can take back — deleted things can be brought back from the “Deleted” page.',
  'ফিরিয়ে নিলাম — শেষ পরিবর্তনের আগের মতো আছে।': 'Taken back — everything is as before the last change.',
  'ওই অংশে কিছু বদলাইনি।': 'Nothing was changed for that part.',
  ' তালিকার বাকি {0}টা আছে।': ' {0} of that list remain.',
  ' তবে ফোনে সেট করা যায়নি — এখনো বাজবে না।': ' But the phone could not set it — it won\'t ring yet.',
  'এই {0}টা কাজ {1} {2}-এর, নির্দিষ্ট দিন নেই। {1} মাসের কত তারিখে {3}-এ মনে করাব?': 'These {0} to-dos are for {1} {2}, with no set day. Which day of {1} should I remind at {3}?',
  'তবে ফোনে সেট করা যায়নি — এখনো বাজবে না।': 'But the phone could not set it — it won\'t ring yet.',
  '{0} তো পার হয়ে গেছে — কিছু রাখিনি।': '{0} has already passed — nothing was kept.',
  '“{0}”-এর রিমাইন্ডার রাখা হয়েছে ({1}), কিন্তু ফোনে সেট করা যায়নি — তাই এখনো বাজবে না। অ্যাপটা একবার বন্ধ করে খুলুন; তবু না হলে রিমাইন্ডার পাতা থেকে আবার চালু করুন।': 'The reminder for “{0}” is kept ({1}), but the phone could not set it — so it won\'t ring yet. Close and reopen the app; if it still fails, turn it on again from the reminders page.',
  '“{0}” কাজটা কোথায় ভাগ হবে বুঝতে পারিনি — কাজগুলোর নাম আলাদা করে বলুন, যেমন “মাছ কেনা, চাল কেনা”।': 'I couldn\'t tell where to split “{0}” — say the to-dos one by one, e.g. “buy fish, buy rice”.',
  'ঠিক আছে — একটার বদলে {0}টা আলাদা কাজ রাখলাম{1}।': 'OK — {0} separate to-dos instead of one{1}.',
