  'এই ফোন': 'This phone',
  'এই ফোন থেকে Drive-এ অটো ব্যাকআপ বন্ধ হবে। Drive-এ রাখা ব্যাকআপ থেকে যাবে।': 'Automatic Drive backup from this phone stops. Backups already in Drive stay.',
  'এই ফোনে অ্যাপের নোটিফিকেশন বন্ধ': 'notifications are off for this app',
  'এই ফোনে আঙুলের ছাপ চালু নেই': 'Fingerprint isn\'t set up on this phone',
  'এই ফোনে আঙুলের ছাপ বা Google অ্যাকাউন্ট যুক্ত নেই, তাই PIN ছাড়া খোলা যাবে না — যাতে ফোন অন্যের হাতে গেলেও আপনার তথ্য নিরাপদ থাকে। Google Drive-এ ব্যাকআপ থাকলে: অ্যাপ মুছে আবার ইনস্টল করুন, একই Google অ্যাকাউন্টে লগইন করে সব ফিরিয়ে আনুন।': 'This phone has no fingerprint or Google account set up in the app, so it cannot open without the PIN — keeping your data safe if the phone is in someone else’s hands. If you have a Google Drive backup: reinstall the app, sign in with the same Google account and bring everything back.',
  'এই ফোনে আঙুলের ছাপ বা ব্যাকআপ-পাসওয়ার্ড চালু নেই, তাই PIN ছাড়া খোলা যাবে না — যাতে ফোন অন্যের হাতে গেলেও আপনার তথ্য নিরাপদ থাকে। Google Drive-এ ব্যাকআপ থাকলে: অ্যাপ মুছে আবার ইনস্টল করুন, একই Google অ্যাকাউন্টে লগইন করে ব্যাকআপ-পাসওয়ার্ড দিয়ে সব ফিরিয়ে আনুন।': 'Fingerprint and backup password are not set up on this phone, so it cannot open without the PIN — this keeps your data safe if the phone is in someone else’s hands. If you have a Google Drive backup: reinstall the app, sign in with the same Google account and restore everything with the backup password.',
  'এই ফোনে এটা খোলার মতো অ্যাপ পাওয়া গেল না': 'No app on this phone can open this',
  'এই ফোনে কথা শুনে লেখার সেবা (Google ভয়েস) পাওয়া যায়নি। Google অ্যাপ চালু/হালনাগাদ করুন, অথবা লিখে দিন।': 'No speech-to-text service (Google voice) on this phone. Turn on or update the Google app, or type instead.',
  'এই ফোনে কোনো ব্যাকআপের খবর নেই।': 'This phone has no record of a backup.',
  'এই ফোনে তথ্য খোলা যায়নি, তাই এখন ব্যাকআপ নেওয়া যাবে না। আগের কোনো ব্যাকআপ ফিরিয়ে আনুন।': 'The data could not be opened on this phone, so a backup can\'t be taken now. Restore an earlier backup.',
  'এই ফোনে “Autostart / Auto-launch / Background” থেকে My Assistant চালু করতে হয়, নইলে ফোন বন্ধ-চালুর পর রিমাইন্ডার আসে না': 'On this phone, My Assistant must be turned on under “Autostart / Auto-launch / Background”, otherwise reminders stop after a restart',
  'এই ফোনের কিছু সেটিং রিমাইন্ডার থামিয়ে দিতে পারে। এক মিনিটে ঠিক করে নেবেন?': 'Some settings on this phone can stop reminders. Fix them in a minute?',
  'এই ফোনের ভয়েস সেবায় বাংলা চালু নেই। Google অ্যাপ → Settings → Voice → Languages থেকে “বাংলা (বাংলাদেশ)” যোগ করুন।': 'Bangla isn\'t on in this phone\'s voice service. Add “বাংলা (বাংলাদেশ)” in the Google app → Settings → Voice → Languages.',
  'এই ফোনের সুরক্ষিত চাবি দিয়ে তথ্যের ফাইল খোলা যাচ্ছে না। অ্যাপ নতুন করে ইনস্টল হলে বা ফোনের নিরাপত্তা বদলালে এমন হতে পারে। পুরনো ফাইলটা মুছে ফেলা হয়নি। ব্যাকআপ থাকলে নিচ থেকে ফিরিয়ে আনুন — পুরনো ফাইলটা আলাদা করে রাখা থাকবে।': 'This phone\'s secure key cannot open the data file. This can happen after a reinstall or a change in the phone\'s security. The old file has not been deleted. If you have a backup, restore it below — the old file will be kept aside.',
  'এই ফোনের সুরক্ষিত চাবি দিয়ে তথ্যের ফাইল খোলা যাচ্ছে না। অ্যাপ নতুন করে ইনস্টল হলে বা ফোনের নিরাপত্তা বদলালে এমন হতে পারে। ব্যাকআপ থাকলে অ্যাপের ডেটা মুছে নতুন করে শুরু করে ব্যাকআপ ফিরিয়ে আনুন।': 'Your data file can\'t be opened with this phone\'s secure key. This can happen after reinstalling the app or changing the phone\'s security. If you have a backup, clear the app\'s data, start again and restore the backup.',
