  'নিচের বক্সে লিখুন বা মাইক চাপুন — স্বাভাবিকভাবে বলুন, একসাথে কয়েকটা কথাও। যেকোনো পাতা খুলতে নাম বলে “খোলো” বলুন, যেমন “নোট খোলো”, “স্বাস্থ্যের পাতায় যাও”, “প্রেসক্রিপশন ফোল্ডার খোলো”। বাঁকা হরফের কথাগুলো হুবহু বলে দেখুন।': 'Type in the box below or tap the mic — speak naturally, several things at once if you like. To open any page, say its name and “খোলো”, e.g. “নোট খোলো”, “স্বাস্থ্যের পাতায় যাও”, “প্রেসক্রিপশন ফোল্ডার খোলো”. Try the lines in italics exactly.',
