  'মুখে বলে সব কাজ, আয়-ব্যয় ও ধার-দেনা (২০ জন), তাগাদার মেসেজ, কাজের তালিকা, ২০টা চালু রিমাইন্ডার, অ্যালার্ম, ক্যালেন্ডার ও নামাজের সময়, নোট, ৩০টা ডকুমেন্ট, পরিবারের সবার স্বাস্থ্য, শিশুর টিকা, ওষুধের রিমাইন্ডার, অভ্যাস, যাকাতের হিসাব, সঞ্চয়, ১টা দোকান, ১টা অন্যান্য হিসাব, ১০টা পাসওয়ার্ড, নিজে চাপলে Google Drive-এ ব্যাকআপ আর নতুন ফোনে সব ফিরিয়ে আনা। আপনার রাখা কোনো তথ্য কখনো তালাবদ্ধ হবে না।': 'Everything by voice, income-spending and loans (20 people), payment-request messages, to-dos, 20 reminders on, alarms, calendar and prayer times, notes, 30 documents, health for the whole family, child vaccines, medicine reminders, habits, zakat, savings, 1 shop, 1 other account, 10 passwords, Google Drive backup by hand and restoring everything on a new phone. Nothing you keep is ever locked.',
