  'যা খুঁজবেন লিখুন — যেমন “রহিম”, “গাড়ির কাগজ”, “বিদ্যুৎ বিল”। মুখে জিজ্ঞেস করতে মাইক চাপুন।': 'Type what to find — e.g. “Rahim”, “car papers”, “electricity bill”. Tap the mic to ask by voice.',
  'যা খুঁজবেন লিখুন — যেমন “রহিম”, “গাড়ির কাগজ”। নিচে সাথে সাথে মিলে যাওয়া জিনিস দেখাবে। কিছু রাখতে বা জিজ্ঞেস করতে লিখে পাঠান (➤) — যেমন “রহিমকে ৫০০ টাকা দিলাম”।': 'Type what to find — e.g. “Rahim”, “car papers”. Matches show below right away. To save or ask something, type it and send (➤) — e.g. “রহিমকে ৫০০ টাকা দিলাম”.',
