  '“প্রতিদিন রাত ১০টায় ওষুধ” বা “প্রতি ৩০ মিনিটে পানি” — এমন রিমাইন্ডার এখানে থাকবে।': 'Reminders like “প্রতিদিন রাত ১০টায় ওষুধ” or “প্রতি ৩০ মিনিটে পানি” appear here.',
  '“রবিনকে ৫০০০ টাকা দিলাম”, “কাল সকাল ১০টায় মিটিং মনে করিয়ে দিও”, “আজকের কাজের তালিকা”': '“রবিনকে ৫০০০ টাকা দিলাম”, “কাল সকাল ১০টায় মিটিং মনে করিয়ে দিও”, “আজকের কাজের তালিকা”',
  '“শেয়ার” চেপে Google Drive বা নিজের WhatsApp-এ পাঠিয়ে রাখুন — ফোন হারালেও ফাইল থাকবে।': 'Tap “Share” and send it to Google Drive or your own WhatsApp — the file survives even if the phone is lost.',
  '• কপি করা পাসওয়ার্ড ৩০ সেকেন্ড পর ক্লিপবোর্ড থেকে মুছে যায়': '• A copied password is cleared from the clipboard after 30 seconds',
  '• ভয়েসে চাইলে অ্যাপ শুধু বলে “স্ক্রিনে দেখুন” — পাসওয়ার্ড জোরে পড়ে না': '• Asked by voice, the app only says “look at the screen” — it never reads the password aloud',
  '• শেষ বদল: {0}': '• Last changed: {0}',
  '▶ চেপে শুনুন, পছন্দ হলে বেছে নিন। “ইন্টারনেট” লেখাগুলো সাধারণত বেশি স্বাভাবিক শোনায়।': 'Tap ▶ to listen and pick the one you like. “Internet” voices usually sound more natural.',
  '✓ কাজ করছে! AI বলল: {0}': '✓ Works! The AI said: {0}',
  'সম্প্রতি কোনো নোট রাখা হয়নি যেটা কাজের তালিকায় সরাব। কাজটা বলুন — সরাসরি কাজের তালিকায় রাখব।': "No note was kept recently to move to the to-do list. Tell me the task and I'll put it straight on the list.",
  'ঠিক বলেছেন — ভুল জায়গায় রেখেছিলাম। {0}টা নোট কাজের তালিকায় সরিয়ে দিলাম।': "You're right — I kept them in the wrong place. Moved {0} notes to the to-do list.",
  '“{0}” নামে {1} জন আছেন — {2}{3}। কাকে {4}?': "There are {1} people named “{0}” — {2}{3}. Whom should I {4}?",
  ', আরও {0} জন': ", and {0} more",
