  'ঠিক আছে, “{0}”-এর নাম এখন “{1}” — {2}টা লেনদেন সহ।{3}{4}': "Done — “{0}” is now “{1}”, with {2} records.{3}{4}",
  ' এই নামে আগের হিসাবের সাথে এক হয়ে গেল।': " It was joined with the existing account of that name.",
  ' আমাকে বলেও করা যায় — যেমন “{0}”।': " You can also tell me — for example “{0}”.",
