  'এখন রমজান চলছে — আজ {0} রোজা (হিজরি হিসাবে; চাঁদ দেখার ওপর এক দিন আগে-পরে হতে পারে)।': "It's Ramadan now — today is fast {0} (by the Hijri calendar; the moon sighting can shift it by a day).",
  'পরের রমজান শুরু হতে পারে {0} {1} — আর {2} দিন। এটা হিজরি হিসাবে আনুমানিক; বাংলাদেশে চাঁদ দেখার ওপর এক দিন আগে-পরে হতে পারে।': "The next Ramadan may begin on {0} {1} — {2} days from now. This is estimated by the Hijri calendar; in Bangladesh the moon sighting can shift it by a day.",
  'স্বাস্থ্যের কোনো মাপ এখনো রাখা নেই। বলুন, যেমন “আজ ওজন ৬৮ কেজি” বা “প্রেশার ১৩০ বাই ৮৫” — তারপর জিজ্ঞেস করলে অবস্থা বলে দেবো।': "No health readings are kept yet. Say, for example, “weight 68 kg today” or “pressure 130 over 85” — then ask and I'll tell you how things stand.",
  'আপনার রাখা শেষ মাপগুলো:': "Your latest readings:",
  'কোন কোন কাজ? একটা একটা করে বলুন, বা এক লাইনে একটা করে লিখুন — সব কাজের তালিকায় রেখে দেব।': "Which tasks? Say them one by one, or type one per line — I'll put them all on the to-do list.",
  ' {0}-এর {1} {2}, {3} — আর {4} দিন।': " {0}'s {1} is {2}, {3} — {4} days from now.",
  'এটা পরামর্শের প্রশ্ন — আপনার রাখা তথ্যে এর উত্তর নেই, আর নিজে থেকে বানিয়ে বলব না। AI চালু থাকলে এমন প্রশ্নে আইডিয়া দিতে পারি।{0}': "That asks for advice — nothing you've kept answers it, and I won't make something up. With AI on, I can give ideas for questions like this.{0}",
  'সাধারণ আয়-ব্যয়ে': "in general income and expense",
