  'এখনো অন্যান্য কোনো হিসাব খোলা হয়নি। বলুন, যেমন “মৃত্তিকা ফাউন্ডেশন নামে অন্যান্য হিসাব খোলো”।': "No separate accounts yet. Say, for example, “open a separate account named Mrittika Foundation”.",
