  'এখন আনতে পারলাম না (ইন্টারনেট বা সার্ভার সাড়া দেয়নি)। bajus.org-এ আজকের দাম দেখে নিজে লিখুন।': 'Couldn\'t get it now (no internet, or the server didn\'t answer). See today\'s price on bajus.org and enter it.',
  '{0}, {1} থেকে কার্যকর — ২২ ক্যারেটের দাম বসানো হলো। গয়না অন্য ক্যারেটের হলে দাম বদলে নিন।': '{0}, in effect from {1} — 22-carat prices filled in. Change them if your jewellery is another carat.',
  'আজকের দাম আনুন (বাজুস)': 'Get today\'s price (BAJUS)',
  'পারি। ডকুমেন্টসে কাগজের ছবি বা PDF যোগ করলে তার ছাপা লেখা ফোনেই পড়ি — নাম, NID বা পাসপোর্ট নম্বর, জন্মতারিখ, ইস্যু আর মেয়াদ শেষের তারিখ, ইনভয়েস-সিরিয়াল-IMEI, ওয়ারেন্টি — যা পাই, তথ্যের ঘরে বসিয়ে দেখাই, আপনি মিলিয়ে নিয়ে রাখবেন। আগে রাখা কাগজেও “ছবি থেকে তথ্য পড়ুন” চাপলে পড়ে দিই। শুধু “১ বছর ওয়ারেন্টি” লেখা থাকলে কেনার তারিখ থেকে হিসাব করি। ইংরেজিতে ছাপা অক্ষর-অঙ্ক সবচেয়ে ভালো পড়া যায়; হাতের লেখা বা বাংলা লেখা এখনো পড়তে পারি না।': 'Yes. When you add a photo or PDF of a paper in Documents, I read its printed text on the phone — name, NID or passport number, date of birth, issue and expiry dates, invoice/serial/IMEI, warranty — and put what I find into its details for you to check before keeping. For papers already kept, tap “Read details from the photo”. If it only says “1 year warranty”, I count from the purchase date. Printed English letters and digits read best; handwriting and Bengali text cannot be read yet.',
  'হ্যাঁ। ডকুমেন্টসে “ওয়ারেন্টি ও গ্যারান্টি” নামে আলাদা ফোল্ডার আছে — কার্ড বা রসিদের ছবি তুলে সেখানে রাখুন। ছবি থেকে ওয়ারেন্টি শেষের তারিখও পড়ে নিতে পারি; প্রিমিয়ামে মেয়াদ শেষের আগে মনে করিয়ে দিই।': 'Yes. Documents has a "Warranty & guarantee" folder — keep a photo of the card or receipt there. I can read the warranty end date from the photo; with Premium I remind you before it runs out.',
