  'অনুরোধটা সারা দেশের সবাই দেখবেন — কার জন্যে, সমস্যা, হাসপাতাল, তারিখ আর আপনার নম্বরসহ। আপনার জেলার যাঁরা দাতা আর এই গ্রুপে দিতে পারেন, তাঁরা নোটিফিকেশনও পাবেন। একসাথে ৩টা পর্যন্ত অনুরোধ খোলা রাখা যায়।': 'Everyone in the country will see this request — who it is for, the problem, the hospital, the date and your number. Donors in your district who can give this group are also notified. Up to 3 requests can be open at a time.',
  'অনুরোধ পাঠানো হয়েছে — তিনি অ্যাপে মেনে নিলে যুক্ত হবেন': 'Request sent — they join when they accept in the app',
  'সদস্য যোগ': 'Add member',
  'ফ্যামিলিতে যুক্ত হতে আগে Google দিয়ে লগইন করুন — সবাই নিজের ইমেইলে যুক্ত হন।': 'Sign in with Google first to use Family — everyone joins with their own e-mail.',
  '{0} জানিয়েছেন আপনি ইন্তেকাল করেছেন': '{0} has reported that you passed away',
  'ভুল হলে এখনই বাতিল করুন। বাতিল না করলে যাচাইয়ের পর ১৪ দিনে তিনি আপনার বেছে রাখা অংশ দেখতে পাবেন।': 'If this is wrong, cancel it now. Otherwise, after a check and 14 days, they will see the parts you chose.',
  'আমি বেঁচে আছি — বাতিল করুন': 'I am alive — cancel it',
  'ফ্যামিলি থেকে এসেছে': 'Came from family',
  'যুক্ত হওয়ার অনুরোধ': 'Requests to join',
  '{0} আপনাকে ফ্যামিলিতে যুক্ত করতে চান': '{0} wants to add you to their family',
  'তিনি আপনাকে বলেছেন: {0}': 'They call you: {0}',
  'যুক্ত হোন': 'Join',
  'আমার ফ্যামিলি': 'My family',
  'এখনো কেউ নেই': 'No one yet',
  'মা-বাবা, স্বামী-স্ত্রী, সন্তান — তাঁদের ইমেইল দিয়ে যুক্ত করুন। তাঁরা যা অনুমতি দেবেন, শুধু তা-ই করতে পারবেন: কাজ, রিমাইন্ডার, ওষুধের রিমাইন্ডার, নোট, লাইভ লোকেশন।': 'Parents, spouse, children — add them by e-mail. You can do only what they allow: to-dos, reminders, medicine reminders, notes, live location.',
  'আপনাকে এখনো কিছুর অনুমতি দেননি': 'Has not allowed you anything yet',
  'অনুমতি: {0}': 'Allowed: {0}',
  'উত্তরের অপেক্ষায় — তিনি অ্যাপ খুলে মেনে নেবেন': 'Waiting — they accept when they open the app',
  'আমার লোকেশন': 'My location',
  'লোকেশন দেখাতে ফোনের অনুমতি লাগবে।': 'Showing your location needs the phone\'s permission.',
  'অ্যাপ খোলা থাকলে লোকেশন যায়। ফোন হারালেও খুঁজে পেতে “সবসময়” অনুমতি দিন।': 'Your location is sent while the app is open. To find a lost phone too, allow it “all the time”.',
  'চালু — অ্যাপ বন্ধ থাকলেও “এখন কোথায়?” জিজ্ঞেস করলে ফোন নিজে জানাবে।': 'On — even with the app closed, the phone answers “Where now?” by itself.',
  'লোকেশনের অনুমতি দিন': 'Allow location',
  '“সবসময় অনুমতি দিন” বেছে নিন': 'Choose “Allow all the time”',
  'লোকেশন তালাবদ্ধ হয়ে যায় — শুধু যাঁদের অনুমতি দিয়েছেন তাঁরাই খুলতে পারেন, আমাদের সার্ভারও না।': 'Your location is locked — only the people you allowed can open it, not even our server.',
  'উত্তরাধিকারী': 'Heirs',
  'কোনো সদস্যকে খুলে “আমার উত্তরাধিকারী” চালু করলে, আপনার ইন্তেকালের পর (কাগজ যাচাই আর ১৪ দিন অপেক্ষার পর) বা আপনি এখনই অনুমতি দিলে তিনি নিচে বাছাই করা অংশ দেখতে পাবেন।': 'Open a member and turn on “My heir”: after your death (a document check and 14 days), or right away if you allow it, they can see the parts chosen below.',
  'উত্তরাধিকারী: {0}। তাঁরা যা দেখতে পাবেন:': 'Heirs: {0}. What they can see:',
  'নিজে টিক না দিলে যাবে না': 'Not included unless you tick it',
  'উত্তরাধিকারীর কপি আপনার ফোনেই তালাবদ্ধ হয়ে সার্ভারে থাকে — শুধু তিনি খুলতে পারেন, আমরা না।': 'The heirs\' copy is locked on your phone before it reaches the server — only they can open it, not us.',
