  'ফোনের চার্জ {0}%': 'Phone battery {0}%',
  'ইন্তেকালের খবর দিন': 'Report a death',
  'মৃত্যু সনদের ছবি লাগবে। আমরা যাচাই করব, তাঁর ফোন আর ইমেইলে জানাব; ১৪ দিনের মধ্যে কেউ বাতিল না করলে তিনি যা বেছে রেখেছেন, আপনি দেখতে পাবেন।': 'A photo of the death certificate is needed. We will check it and tell their phone and e-mail; if no one cancels within 14 days, you will see what they chose.',
  'কিছু লিখতে চাইলে (তারিখ, কোথায়)': 'Anything to add (date, where)',
