  'উত্তরাধিকার': 'Heirs',
  'আমার উত্তরাধিকারী': 'My heir',
  'আমার ইন্তেকালের পর (কাগজ যাচাই আর ১৪ দিন পর) ফ্যামিলি পাতায় বাছাই করা অংশ দেখবেন': 'After my death (a document check and 14 days) they see the chosen parts on the Family page',
