  'খবর দেওয়া হয়েছে — যাচাই চলছে': 'Reported — being checked',
  'যাচাই হয়েছে — {0} থেকে দেখা যাবে': 'Checked — opens on {0}',
  'তিনি জীবিত থাকতে পুরো অ্যাক্সেস না দিলে, ইন্তেকালের পর খবর দিয়ে দেখা যাবে': 'Unless they give full access while alive, it opens after a death is reported',
  'ফ্যামিলি থেকে সরাবেন?': 'Remove from family?',
  'দুজনের দেওয়া সব অনুমতি, উত্তরাধিকার আর লোকেশন দেখা বন্ধ হবে।': 'All permissions between you, heirs and location sharing will stop.',
  'ফ্যামিলি থেকে সরান': 'Remove from family',
  'দিন ছাড়া': 'No date',
  'দিন বেছে নিন': 'Choose a day',
  'কয়টায়': 'At what time',
