  'কত দিন: {0} দিন': 'How long: {0} days',
  'কী, লিখে দিন': 'Write what it is',
  'অন্তত একটা সময় বেছে নিন': 'Choose at least one time',
  '{0} পর্যন্ত যা ছিল — শুধু দেখা যায়, বদলানো যায় না': 'As it was on {0} — view only, cannot be changed',
  'তাঁর কাছে পাওনা': 'They owe',
  'তাঁকে দিতে হবে': 'Owed to them',
  'শেষ আয়-ব্যয়': 'Latest income and expenses',
  'যাকাতের হিসাবে যোগ করুন': 'Add to the zakat count',
  'কী (যেমন: জমির বায়নার টাকা, প্রাইজবন্ড)': 'What (e.g. land advance, prize bonds)',
  'সম্পদ': 'Asset',
  'আলাদা লেনদেন নেই — আপনার লেখা পরিমাণ': 'No separate transactions — the amount you entered',
