  'মোট সম্পদ {0} − দেনা {1}': 'Total assets {0} − debts {1}',
  'যাকাতের বছর কবে শুরু, দিন দিলে পরের যাকাতের দিন মনে করিয়ে দেব': 'Give the day your zakat year started and I will show the next zakat day',
  'পরের যাকাতের দিন: {0} ({1})': 'Next zakat day: {0} ({1})',
  'তারিখ দিন': 'Set date',
  'যাকাত কী, কার ওপর, কীভাবে হিসাব': 'What zakat is, who pays, how it is counted',
  '• নিসাব: সাড়ে ৫২ ভরি রুপা (বা সাড়ে ৭ ভরি সোনা) সমান সম্পদ এক চান্দ্র বছর ধরে থাকলে যাকাত ফরজ।\n• হার: যাকাতযোগ্য সম্পদের ২.৫% (৪০ ভাগের ১ ভাগ)।\n• ধরা হয়: নগদ, ব্যাংক ও মোবাইল ব্যাংকিংয়ের টাকা, সঞ্চয়, DPS-এ জমা, সোনা-রুপা, ব্যবসার মাল, ফেরত পাওয়ার আশা আছে এমন পাওনা।\n• ধরা হয় না: থাকার বাড়ি, নিজের ব্যবহারের গাড়ি-আসবাব, সংসারের জিনিস।\n• বাদ যায়: যে দেনা শোধ করতে হবে।\n• কাদের দেওয়া যায়: গরিব, মিসকিন, ঋণগ্রস্ত, মুসাফির ইত্যাদি (সূরা তাওবা ৬০)।\nএটা আনুমানিক হিসাব — নিশ্চিত হতে আলেমের পরামর্শ নিন।': '• Nisab: zakat is due when wealth equal to 52.5 vori of silver (or 7.5 vori of gold) is held for a lunar year.\n• Rate: 2.5% (one fortieth) of zakatable wealth.\n• Counted: cash, bank and mobile-banking money, savings, DPS deposits, gold and silver, business stock, money owed to you that you expect back.\n• Not counted: the home you live in, your own car and furniture, household things.\n• Taken off: debts you must pay.\n• Who can receive it: the poor, the needy, people in debt, travellers and others (Surah At-Tawbah 60).\nThis is an estimate — ask a scholar to be sure.',
  'হিসাব কোথা থেকে এল': 'Where the count comes from',
  'আয়-ব্যয়, অ্যাকাউন্ট, সঞ্চয়, কিস্তি আর ধার-দেনা থেকে নিজে আসে; সেখানে বদলালে এখানেও বদলায়। টিক তুলে দিলে সেটা বাদ যাবে, চাপলে কোন লেনদেন থেকে এল দেখাবে।': 'It comes by itself from income-expense, accounts, savings, instalments and loans; change them there and it changes here. Untick a line to leave it out; tap it to see the transactions behind it.',
  'এখনো কিছু নেই — অ্যাকাউন্ট, ধার-দেনা বা নিচে সোনা-রুপা লিখলে এখানে আসবে।': 'Nothing yet — add accounts, loans, or gold and silver below and they will show here.',
  'নিজে কিছু যোগ করুন': 'Add something yourself',
  'মুখেও জিজ্ঞেস করা যায়: “আমার যাকাত কত?” — এই পাতার একই হিসাব থেকে উত্তর আসে।': 'You can also ask by voice: “How much is my zakat?” — the answer comes from this same count.',
  'রক্ত দরকার হলে অনুরোধ দিন — কার জন্যে, সমস্যা, হাসপাতাল, তারিখ আর নম্বরসহ; সারা দেশের সবাই দেখবেন, আপনার জেলার দাতারা নোটিফিকেশনও পাবেন। দাতা হলে “আমি দিতে পারব” বলতে পারবেন।': 'Ask for blood with who it is for, the problem, the hospital, the date and a number; everyone in the country sees it and donors in your district are notified. As a donor you can say “I can give”.',
  'ব্লাড ডোনেশন খোলো': 'Open blood donation',
  'পরিবারের সদস্যদের ইমেইলে যুক্ত করে তাঁদের জন্য কাজ, রিমাইন্ডার, ওষুধের রিমাইন্ডার, নোট দেওয়া; অনুমতি থাকলে লাইভ লোকেশন; উত্তরাধিকারী (প্রিমিয়াম)।': 'Add family members by e-mail and give them to-dos, reminders, medicine reminders and notes; live location if they allow; heirs (Premium).',
  'ফ্যামিলি খোলো': 'Open family',
  'পরিবারের কারো জন্য কথায় কাজ বা রিমাইন্ডার পাঠানো': 'Sending a to-do or reminder to a family member by voice',
  'লোকেশন কীভাবে ব্যবহার হয়': 'How location is used',
  'My Assistant আপনার ফোনের লোকেশন নেয় — অ্যাপ বন্ধ থাকলেও — শুধু তখন, যখন আপনি যাঁদের অনুমতি দিয়েছেন সেই পরিবারের কেউ “এখন কোথায়?” জিজ্ঞেস করেন (যেমন ফোন হারালে খুঁজতে)। লোকেশন তালাবদ্ধ হয়ে শুধু তাঁদের কাছে যায়; আমরা দেখতে পারি না, বিজ্ঞাপনে বা অন্য কিছুতে ব্যবহার হয় না। ফ্যামিলি পাতা থেকে যেকোনো সময় বন্ধ করা যায়।': 'My Assistant reads your phone\'s location — even when the app is closed — only when a family member you allowed asks “Where now?” (for example to find a lost phone). It is locked and goes only to them; we cannot see it, and it is never used for ads or anything else. You can turn it off on the Family page at any time.',
