  'ব্যয়ে যোগ হলো। {0} এর বকেয়া শেষ': 'Added to spending. Nothing more owed to {0}',
  'ধার-দেনার মতোই: কেউ বাকিতে নিলে বা আপনি বাকিতে নিলে লিখুন — কে, কী, কত টাকা, কবে শোধ। সেদিন মনে করিয়ে দেবো।': 'Just like loans: when someone takes on credit, or you do, write it here — who, what, how much, when it\'s paid. I\'ll remind you that day.',
  'প্রিমিয়াম চালু হয়েছে': 'Premium is on',
  'রিমাইন্ডার, ব্যাকআপ, ফ্যামিলি — সব প্রিমিয়াম সুবিধা এখন চালু। ধন্যবাদ!': 'Reminders, backup, family — every Premium feature is on now. Thank you!',
  'ফ্রি': 'Free',
  'ট্রায়াল': 'Trial',
  'শেষ কবে রক্ত দিয়েছেন জানা নেই। বলুন, যেমন “শেষ রক্ত দিয়েছি ১০ আগস্ট” — তিন মাস পরের দিনটা বলে দেবো।': 'I don\'t know when you last gave blood. Say, e.g. “I last gave blood on 10 August” — I\'ll tell you the day three months later.',
  'শেষ দিয়েছেন {0}। আবার দিতে পারবেন {1} থেকে ({2})।': 'Last given {0}. You can give again from {1} ({2}).',
  'শেষ দিয়েছেন {0} — তিন মাস পেরিয়েছে, এখন দিতে পারবেন।': 'Last given {0} — three months have passed, you can give now.',
  'রেখে দিলাম — শেষ রক্ত দিয়েছেন {0}। আবার দিতে পারবেন {1} থেকে।': 'Saved — you last gave blood on {0}. You can give again from {1}.',
  '[শেষ রক্তদানের দিন রাখা হলো]': '[Last blood donation date saved]',
  '{0} আয় {1} টাকা, খরচ {2} টাকা — {3} {4} টাকা।': '{0} income {1} taka, spent {2} taka — {3} {4} taka.',
  'আয়ের চেয়ে বেশি খরচ': 'spent more than income',
  'আপনার তথ্য আপনার ফোনেই থাকে, PIN দিয়ে তালা দেওয়া। পাসওয়ার্ড, পিন আর ওটিপি কখনো ফোনের বাইরে যায় না। ব্যাকআপ যায় আপনার নিজের Google Drive-এ, তালা দেওয়া অবস্থায়। ফ্যামিলিতে কিছু পাঠালে শুধু সেই মানুষটাই খুলতে পারেন। AI চালু থাকলে শুধু যে কথাটা বুঝতে সাহায্য লাগে সেটুকু যায়।': 'Your data stays on your phone, locked with your PIN. Passwords, PINs and OTPs never leave the phone. Backups go to your own Google Drive, locked. Anything sent to family can be opened only by that person. With AI on, only the sentence that needs help understanding is sent.',
  '{0} কোনো কাজ, রিমাইন্ডার বা বিশেষ দিন রাখা নেই।': 'No tasks, reminders or special days {0}.',
  '{0} {1}টা আছে —': '{0}: {1} items —',
  'আর {0} দিন': '{0} days to go',
  'কোন হিসাবে বকেয়া?': 'Which account is the due in?',
  'বাড়ি বানানো, দোকান, অফিসের কাজ, কোনো অর্ডার — প্রতিটার আলাদা আয়-ব্যয় আর বকেয়া রাখুন। কত এলো, কত গেল, কে কত বাকি দেখবেন।': 'Building a house, a shop, office work, an order — keep separate income, spending and dues for each. See what came in, what went out and who owes what.',
