  'এখন থেকে নতুন করে হিসাব শুরু হবে': 'Counting starts afresh from now',
  'হাতে, ব্যাংকে, বিকাশে — সব মিলিয়ে লিখুন। এরপর আয়, খরচ, ধার আর অন্যান্য হিসাবের খরচ লিখলে নিজে বাড়বে-কমবে।': 'Cash, bank, bKash — write it all together. After that it goes up and down with income, spending, loans and other accounts’ spending.',
  'এখন আছে কীভাবে হলো': 'How “You have now” came about',
  'এখনো “এখন আছে” দেওয়া হয়নি।': '“You have now” has not been set yet.',
  'শুরুতে ছিল ({0})': 'At the start ({0})',
  'ধার দিলে ব্যয়ে দেখায়, ধার নিলে আয়ে — খরচ বা আয় নয়, টাকা আসা-যাওয়া। অন্যান্য হিসাবের খরচ এখান থেকেই যায়; বকেয়া পেলে আয়ে আসে।': 'Lending shows as outgoing, borrowing as incoming — not spending or earning, just money moving. Other accounts’ spending comes from here; a due collected comes in as income.',
