  'অন্যান্য হিসাবের আয়': 'Other accounts’ income',
  'অন্যান্য হিসাবের খরচ': 'Other accounts’ spending',
  'খরচ মূল টাকা থেকে যায়। এই কাজে টাকা পেলে আয়-ব্যয়ে আয় হিসেবে লিখুন; বকেয়া পেলে নিচে বকেয়া থেকে আদায় দিন।': 'Spending comes from the main money. Money received for this work goes in income & spending as income; a due collected, below under dues.',
