  'বিসমিল্লাহির রাহমানির রাহীম।\n\nআমি, {0}, সুস্থ মস্তিষ্কে, কারো চাপ ছাড়া এই ওছিয়ত করছি।\n\n১. আমার দেনা: …\n২. আমার পাওনা: …\n৩. আমার সম্পদের এক-তৃতীয়াংশের মধ্যে ওছিয়ত: …\n৪. জানাজা ও দাফন: …\n৫. পরিবারের জন্য কথা: …\n\nবাকি সম্পদ ইসলামি উত্তরাধিকার আইন অনুযায়ী ভাগ হবে।': 'Bismillahir Rahmanir Rahim.\n\nI, {0}, of sound mind and under no pressure, make this will.\n\n1. My debts: …\n2. Owed to me: …\n3. Bequests within one third of my wealth: …\n4. Janaza and burial: …\n5. Words for my family: …\n\nThe rest of my wealth is to be divided by Islamic inheritance law.',
