  'এই ফোনে তালাবদ্ধ থাকে। ফ্যামিলিতে উত্তরাধিকারী রাখলে আর “নোট” দেখার অনুমতি দিলে তিনি পরে দেখতে পাবেন। বদলালে নতুন তারিখ দেখাবে।': 'Locked on this phone. If you keep an heir in Family and let them see notes, they can read it later. Changing it shows the new date.',
