  'অন্যান্য হিসাব (“{0}”) প্রিমিয়াম সুবিধা, তাই কিছু লিখিনি। সাধারণ আয়-ব্যয়ে চাইলে বলুন।': 'Other accounts (“{0}”) are a Premium feature, so nothing was written. Say so if you want it in your income and spending.',
