  '২০টা পাসওয়ার্ড': '20 passwords',
  'ফ্যামিলি: উত্তরাধিকার, পুরো অ্যাক্সেস, লোকেশন': 'Family: heirs, full access, location',
  'উত্তরাধিকারী রাখা, এখনই পুরো অ্যাক্সেস দেওয়া, লাইভ লোকেশন দেখানো; উত্তরাধিকারী এক চাপে সব ব্যাকআপ নিতে পারেন': 'Keep heirs, give full access now, share live location; an heir can take a full backup in one tap',
  'সদস্য যুক্ত করা, কাজ, রিমাইন্ডার, ওষুধের রিমাইন্ডার আর নোট পাঠানো': 'Adding members, sending tasks, reminders, medicine reminders and notes',
  'AI উত্তর': 'AI answers',
  'অ্যাপ নিজের নিয়মে বোঝে আর উত্তর দেয়': 'The app understands and answers by its own rules',
  'উত্তরাধিকার, পুরো অ্যাক্সেস, লোকেশন': 'Heirs, full access, location',
  'মুখে বলে সব কাজ, আয়-ব্যয়, এখন আছে, ধার-দেনা (যত জন খুশি) ও তার রিমাইন্ডার, তাগাদার মেসেজ, কাজের তালিকা, অ্যালার্ম, ক্যালেন্ডার ও নামাজের সময়, নোট, কাগজের মেয়াদের খবর, সব মাসের রিপোর্ট, নিজের স্বাস্থ্য, শিশুর টিকা, ওষুধের রিমাইন্ডার, অভ্যাস, বিশেষ দিন, যাকাতের হিসাব, সঞ্চয়, দোকান ও রসিদ, স্মার্ট খেয়াল, ফ্যামিলিতে কাজ-রিমাইন্ডার-নোট পাঠানো, নিজে চাপলে Google Drive-এ ব্যাকআপ আর নতুন ফোনে সব ফিরিয়ে আনা। আপনার রাখা কোনো তথ্য কখনো তালাবদ্ধ হবে না।': 'Everything by voice, income and spending, money now, loans (any number of people) and their reminders, reminder messages, to-dos, alarms, calendar and prayer times, notes, paper expiry alerts, reports for every month, your own health, child vaccines, medicine reminders, habits, special days, zakat, savings, shop and receipts, smart notices, sending tasks, reminders and notes in Family, Google Drive backup by hand and bringing everything back on a new phone. Nothing you keep is ever locked.',
  'এক চাপে সব ব্যাকআপ নিন': 'Take a full backup in one tap',
  'সব ব্যাকআপ সেভ হলো: {0}': 'Full backup saved: {0}',
  'ব্যাকআপ সেভ হলো: {0} — {1}টা ছবি/ফাইল এখনো আসেনি': 'Backup saved: {0} — {1} photos/files have not come yet',
  'নাম বা ট্যাগ দিন — পরে জিজ্ঞেস করলে এ দিয়েই খুঁজে দেবে': 'Give a name or a tag — that is how it will be found when you ask later',
  'ফোল্ডার বেছে নিন — মিলছে না? “নতুন ফোল্ডার” বানান': 'Choose a folder — none fits? Make a “New folder”',
  'নাম *': 'Name *',
  'নাম বা ট্যাগ — অন্তত একটা দিতে হবে': 'A name or a tag — at least one is needed',
  'ফোল্ডার *': 'Folder *',
  'যে ফোল্ডারের যে নাম, তাতে শুধু সেই কাগজ। অন্য কিছু হলে নতুন ফোল্ডার বানান।': 'Each folder holds only what its name says. For anything else, make a new folder.',
  'কোনটার পাসওয়ার্ড?': 'Password for which one?',
  'আজ নিজের জন্য ছোট একটা ধাপ': 'One small step for yourself today',
  '{0}-এর জন্য ছোট একটা ধাপ': 'One small step for {0}',
  'আজ ২০ মিনিট হাঁটুন — ছোট ছোট পা-ই বড় বদল আনে।': 'Walk 20 minutes today — small steps make a big change.',
  'পানি বেশি, চিনি কম — আজ একটা মিষ্টি পানীয় বাদ দিয়ে দেখুন।': 'More water, less sugar — skip one sweet drink today.',
  'প্লেটের অর্ধেক সবজি রাখুন — পেট ভরবে, ভাত লাগবে কম।': 'Fill half the plate with vegetables — you will be full with less rice.',
  'লিফট নয়, সিঁড়ি — প্রতিটা ধাপই কাজে লাগে।': 'Stairs, not the lift — every step counts.',
  'রাতের খাবার একটু আগে আর একটু কম — ঘুমও ভালো হবে।': 'Dinner a little earlier and a little less — you will sleep better too.',
  'সপ্তাহে আধা কেজি কমানোই যথেষ্ট — ধীরে, কিন্তু নিয়মিত।': 'Half a kilo a week is enough — slowly, but steadily.',
  'ভাজাপোড়ার বদলে আজ ফল খান — শরীর ধন্যবাদ দেবে।': 'Fruit instead of fried snacks today — your body will thank you.',
  'নামাজের পর ১০ মিনিট হাঁটা — অভ্যাস হয়ে গেলে আর কষ্ট লাগবে না।': 'A 10-minute walk after prayer — once it is a habit, it is easy.',
  'বিকাশে টাকা দিয়ে প্রিমিয়াম নেওয়া যায়': 'Premium is paid by bKash',
  'উত্তরাধিকার, পুরো অ্যাক্সেস আর লোকেশন প্রিমিয়াম সুবিধা': 'Heirs, full access and location are Premium features',
  '“এখন আছে” কত টাকা আর কীভাবে হলো; নিজের আয় আর খরচ খাত ধরে; ধার আর অন্যান্য হিসাবের টাকা নিজে যুক্ত হয়।': 'How much money you have now and how it came to be; your own income and spending by category; loans and other accounts join by themselves.',
  'কে কত পাবে, কাকে কত দিতে হবে, বকেয়াসহ; ফেরতের তারিখে মনে করায়; এক চাপে তাগাদার মেসেজ।': 'Who owes whom, dues included; a reminder on the pay-back day; a reminder message in one tap.',
  'প্রতিটা কাজের (বাড়ি, বিয়ে, ব্যবসা) আলাদা খরচ, বকেয়া আর বাজেট; টাকা মূল হিসাবে নিজে যুক্ত হয় (প্রিমিয়াম)।': 'Separate spending, dues and budget for each job (house, wedding, business); the money joins your main money by itself (Premium).',
  '“এখন আছে”, ধার-দেনা, বকেয়া, সঞ্চয় আর সোনা-রুপা ধরে যাকাতের হিসাব; আজকের ভরির দাম নিজে আনে।': 'Zakat from your money now, loans, dues, savings and gold and silver; today\'s price per vori is fetched.',
  'দোকানের নাম, নম্বর, ঠিকানা; বিক্রি, খরচ, কাস্টমারের বাকি আর রসিদ।': 'Shop name, number, address; sales, costs, customer dues and receipts.',
  'যা যা চান বেছে নিয়ে এক PDF-এ — ডাউনলোড, শেয়ার বা প্রিন্ট (প্রিমিয়াম)।': 'Pick what you want into one PDF — download, share or print (Premium).',
  'BMI, প্রেশার, সুগার, ওজন — গ্রাফসহ; BMI বেশি হলে উৎসাহের নোটিফিকেশন; শিশুর টিকার কার্ড; ডাক্তারকে দেখানোর সারাংশ। পরিবারের সদস্য যুক্ত করা প্রিমিয়ামে।': 'BMI, pressure, sugar, weight with graphs; an encouraging notice when BMI is high; child vaccine card; a summary for the doctor. Adding family members is Premium.',
  'দিনের কথা লিখে রাখা; নিচে অভ্যাস, ওষুধ, বিশেষ দিন আর তৈরি তালিকা।': 'Write about your day; habits, medicines, special days and ready lists below.',
  'যা মনে রাখতে চান; বিভাগ ধরে সাজানো, ছবি-ফাইল যোগ করা যায়, টিক-চিহ্নের তালিকাও। উপরে ওছিয়তনামা।': 'What you want to remember, by category, with photos and files, or as a checklist. Your will is at the top.',
  'NID, পাসপোর্ট, জমির কাগজ, প্রেসক্রিপশন, ওয়ারেন্টি, পরিবারের ছবি — নিজের নামের ফোল্ডারে, তালাবদ্ধ; অন্য কিছুর জন্য নতুন ফোল্ডার। প্রতিটার নাম বা ট্যাগ দিতে হয়, পরে বলে খোঁজা যায়।': 'NID, passport, land papers, prescriptions, warranties, family photos — each in its own folder, locked; make a new folder for anything else. Each needs a name or a tag, so you can find it by asking.',
  'Facebook, WhatsApp, Gmail, বিকাশ — এক চাপে নাম বসে; Wi-Fi, ব্যাংকের লগইন; দেখতে আঙুলের ছাপ বা PIN লাগে, কখনো জোরে পড়া হয় না।': 'Facebook, WhatsApp, Gmail, bKash — the name in one tap; Wi-Fi, bank logins; fingerprint or PIN to see, never read aloud.',
  'রক্ত দরকার হলে অনুরোধ দিন — কার জন্যে, সমস্যা, হাসপাতাল, তারিখ আর নম্বরসহ; আপনার জেলার যাঁদের গ্রুপ মেলে, তাঁরা নোটিফিকেশন পান। মোবাইল নম্বর দিয়ে নিজেও দাতা হতে পারেন।': 'Ask for blood — for whom, the problem, hospital, date and number; donors in your district with a matching group are notified. Become a donor yourself with your mobile number.',
  'পরিবারের সদস্যদের ইমেইলে যুক্ত করে কাজ, রিমাইন্ডার, ওষুধের রিমাইন্ডার, নোট পাঠানো। ফোন হারালে “এখন কোথায়?” চেপে লোকেশন; উত্তরাধিকারী এক চাপে সব ব্যাকআপ পান (লোকেশন আর উত্তরাধিকার প্রিমিয়ামে)।': 'Add family by e-mail and send tasks, reminders, medicine reminders and notes. A lost phone: tap “Where now?” for its location; an heir gets a full backup in one tap (location and heirs are Premium).',
  'নাম, জেলা (ফোনের লোকেশন অনুযায়ী), রক্তের গ্রুপ, রক্তদান, ভাষা, থিম ও নিজের রং, সহজ মোড, তালা, ব্যাকআপ, মতামত পাঠানো।': 'Name, district (from the phone\'s location), blood group, blood donation, language, theme and your colour, easy mode, lock, backup, feedback.',
  'সব তথ্য তালাবদ্ধ হয়ে নিজের Google Drive-এ বা ফাইলে; ফোন হারালে বা বদলালে নতুন ফোনে সব ফিরে আসে।': 'Everything locked in your own Google Drive or a file; if the phone is lost or changed, it all comes back on the new one.',
  'যত খুশি রিমাইন্ডার, ডকুমেন্ট আর পাসওয়ার্ড; অন্যান্য হিসাব, ওছিয়তনামা, পরিবারের স্বাস্থ্য, উত্তরাধিকার ও লোকেশন, অটো ব্যাকআপ, PDF, AI উত্তর — বিজ্ঞাপন ছাড়া। পেমেন্ট বিকাশে।': 'Unlimited reminders, documents and passwords; other accounts, will, family health, heirs and location, auto backup, PDF, AI answers — no ads. Paid by bKash.',
  'পাসপোর্ট, লাইসেন্স, ট্যাক্স টোকেনের মেয়াদ শেষের আগে মনে করায় (২০টা রিমাইন্ডারের মধ্যে ধরা)।': 'Reminds before a passport, licence or tax token expires (counted within the 20 reminders).',
  'নিজের ওছিয়ত লিখে রাখা, কবে শেষ বদলেছেন তারিখসহ; উত্তরাধিকারী পরে দেখতে পান (প্রিমিয়াম)।': 'Write your will, with the date it was last changed; your heir can see it later (Premium).',
