  'ব্যাকআপে আপনার নিজের একটা পাসওয়ার্ডও লাগবে। কেউ আপনার Google অ্যাকাউন্ট দখল করলেও এই পাসওয়ার্ড ছাড়া ব্যাকআপ খুলতে পারবে না।\n\nসাবধান: পাসওয়ার্ড ভুলে গেলে নতুন ফোনে ব্যাকআপ আর খোলা যাবে না — কেউ উদ্ধার করতে পারবে না। কোথাও লিখে রাখুন।': 'The backup will also need a password of your own. Even someone who takes over your Google account cannot open it without this password.\n\nCareful: if you forget it, the backup cannot be opened on a new phone — no one can recover it. Write it down somewhere.',
