  'চালু — ব্যাকআপ খুলতে Google অ্যাকাউন্ট আর আপনার পাসওয়ার্ড দুটোই লাগে': 'On — opening the backup needs both the Google account and your password',
  'বন্ধ — Google অ্যাকাউন্ট দখল হলেও ব্যাকআপ যেন খোলা না যায়': 'Off — so the backup cannot be opened even if the Google account is taken over',
  'ব্যাকআপের পাসওয়ার্ড মেলেনি। এখনকার তথ্যে কোনো পরিবর্তন হয়নি।': 'The backup password did not match. Nothing on this phone was changed.',
  'নিরাপত্তা কোড': 'Safety code',
